SELECT CASE WHEN unit_price >= 450 THEN 'high' WHEN unit_price >= 150 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(unit_price) AS max_unit_price, MAX(unit_price) - MIN(unit_price) AS unit_price_range, ROUND(AVG(unit_price), 2) AS avg_unit_price FROM order_items WHERE product_id = 27 AND product_id IS NOT NULL GROUP BY unit_price_bucket ORDER BY max_unit_price, unit_price_range DESC, unit_price_bucket LIMIT 50
